*/
scwin.ipt_lstPrtdepoShrs_onkeyup = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_lstPrtdepoShrs_onkeyup — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        (selfVar.value = $c.num.formatNumber(selfVar.value));
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil55210.ipt_lstPrtdepoShrs_onkeyup' }); }
};

