    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_saveLstPrtdepoShrs_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
